(5172799, 752930, 96751, '<td valign="top">One of the few sand "action shots".  Nice work.  The crop is a bit odd though.</td>', 'One of the few sand "action shots".  Nice work.  The crop is a bit odd though.', '2009-01-05 13:33:30.000000', NULL, 1),
(5172800, 752374, 6667, '<td valign="top">Cleveland- You move up immediately:-)  Nice scene.</td>', 'Cleveland- You move up immediately:-)  Nice scene.', '2009-01-05 13:33:45.000000', NULL, 1),
(5172803, 751127, 96751, '<td valign="top">Beautiful still life.  Had the lighting been focused a bit lower towards the sand and branch, it would have been a stronger "sand" submission.</td>', 'Beautiful still life.  Had the lighting been focused a bit lower towards the sand and branch, it would have been a stronger "sand" submission.', '2009-01-05 13:34:18.000000', NULL, 1),
(5172804, 753130, 96751, '<td valign="top">Perfect lighting.  Great shot.  Tilt really adds interest.  I''ve been kind of picky though with the "sand challenge" thing, which to me should be the main element in the shot.  Otherwise a perfect capture.</td>', 'Perfect lighting.  Great shot.  Tilt really adds interest.  I''ve been kind of picky though with the "sand challenge" thing, which to me should be the main element in the shot.  Otherwise a perfect capture.', '2009-01-05 13:35:38.000000', NULL, 1),
(5172807, 752871, 96751, '<td valign="top">If only the sand would have been sharper, this would have been perfect.</td>', 'If only the sand would have been sharper, this would have been perfect.', '2009-01-05 13:36:08.000000', NULL, 1),
(5172811, 752332, 96751, '<td valign="top">Very interesting shot but really lacks lighting.</td>', 'Very interesting shot but really lacks lighting.', '2009-01-05 13:38:08.000000', NULL, 1),
(5172815, 752797, 96751, '<td valign="top">Like the colors and the reflections but it''s hard to know where to look.</td>', 'Like the colors and the reflections but it''s hard to know where to look.', '2009-01-05 13:38:50.000000', NULL, 1),
(5172818, 752630, 96751, '<td valign="top">Very creative take on a cliche.  Nice work.  Very zen.</td>', 'Very creative take on a cliche.  Nice work.  Very zen.', '2009-01-05 13:39:25.000000', NULL, 1),
(5172823, 753207, 96751, '<td valign="top">Gorgeous shot.  I''m adding to my faves.  But perhaps without all the fabulous vegetation behind it and around it, this might have passed more as "sand".</td>', 'Gorgeous shot.  I''m adding to my faves.  But perhaps without all the fabulous vegetation behind it and around it, this might have passed more as "sand".', '2009-01-05 13:40:51.000000', NULL, 1),
(5172825, 752744, 96751, '<td valign="top">I can feel the current...  I''m wondering of backlighting them all to emphasize the sand more would have made this more about the sand?</td>', 'I can feel the current...  I''m wondering of backlighting them all to emphasize the sand more would have made this more about the sand?', '2009-01-05 13:41:48.000000', NULL, 1),
(5172826, 752738, 43774, '<td valign="top">I love it!!!!! Wish I could give you more than a 10.</td>', 'I love it!!!!! Wish I could give you more than a 10.', '2009-01-05 13:41:49.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5172830, 752871, 43774, '<td valign="top">Really nice. The tilted horizon bothers me just a bit but that''s because I''m picky about horizons. Love the light on the sea urchin although my first thought was that this was the desert, not the beach. 9 from me.</td>', 'Really nice. The tilted horizon bothers me just a bit but that''s because I''m picky about horizons. Love the light on the sea urchin although my first thought was that this was the desert, not the beach. 9 from me.', '2009-01-05 13:43:14.000000', NULL, 1),
(5172832, 753099, 43774, '<td valign="top">Dramatic sky and processing. Love that fallen fence.</td>', 'Dramatic sky and processing. Love that fallen fence.', '2009-01-05 13:43:36.000000', NULL, 1),
(5172836, 752752, 43774, '<td valign="top">Love your title and the colours in this as well as the perspective and composition. Well done.</td>', 'Love your title and the colours in this as well as the perspective and composition. Well done.', '2009-01-05 13:44:06.000000', NULL, 1),
(5172840, 753130, 43774, '<td valign="top">I think the tilt works here (and I usually hate tilt).</td>', 'I think the tilt works here (and I usually hate tilt).', '2009-01-05 13:44:30.000000', NULL, 1),
(5172850, 753026, 70265, '<td valign="top">Great texture in the sand, like the sepia tones.</td>', 'Great texture in the sand, like the sepia tones.', '2009-01-05 13:45:56.000000', NULL, 1),
(5172859, 752974, 70265, '<td valign="top">like the saturated colors</td>', 'like the saturated colors', '2009-01-05 13:47:40.000000', NULL, 1),
(5172862, 753096, 96751, '<td valign="top">Very interesting picture.  The mirror is a very unexpected element.  Perhaps oversharpened as a whole.</td>', 'Very interesting picture.  The mirror is a very unexpected element.  Perhaps oversharpened as a whole.', '2009-01-05 13:48:24.000000', NULL, 1),
(5172864, 753099, 70265, '<td valign="top">A fav in this challenge! Love the perspective, angles, black &amp; White tones.</td>', 'A fav in this challenge! Love the perspective, angles, black & White tones.', '2009-01-05 13:48:48.000000', NULL, 1),
(5172866, 752985, 96751, '<td valign="top">Love the different types of sand, and the footprint detail.  Nice colors and shapes.</td>', 'Love the different types of sand, and the footprint detail.  Nice colors and shapes.', '2009-01-05 13:49:05.000000', NULL, 1),
(5172870, 753099, 96751, '<td valign="top">Great fisheye distortion.  Really draws the eye to the center - but unfortunately not to the "sand", which is almost an incidental element here.  Powerful, but not as "sandy" as some of the other submissions.</td>', 'Great fisheye distortion.  Really draws the eye to the center - but unfortunately not to the "sand", which is almost an incidental element here.  Powerful, but not as "sandy" as some of the other submissions.', '2009-01-05 13:50:27.000000', NULL, 1),
(5172875, 752752, 70265, '<td valign="top">Nice texture in the sand and I like how you were able to get just the one row of prints.</td>', 'Nice texture in the sand and I like how you were able to get just the one row of prints.', '2009-01-05 13:50:52.000000', NULL, 1),
(5172878, 753155, 96751, '<td valign="top">Interesting combination of color and b/w.  Not sure it works for me, and the "sand" is too incidental.</td>', 'Interesting combination of color and b/w.  Not sure it works for me, and the "sand" is too incidental.', '2009-01-05 13:51:32.000000', NULL, 1),
(5172882, 752738, 96751, '<td valign="top">LOL!  Beach in a Jar.  GREAT idea, wonderful execution.  Best of the studio shots IMO.  A tad more contrast on the stars - like on the palm tree trunks - would have been even better.</td>', 'LOL!  Beach in a Jar.  GREAT idea, wonderful execution.  Best of the studio shots IMO.  A tad more contrast on the stars - like on the palm tree trunks - would have been even better.', '2009-01-05 13:52:44.000000', NULL, 1),
(5172883, 752974, 96751, '<td valign="top">The oversaturation really detracts from an otherwise beautiful shot.</td>', 'The oversaturation really detracts from an otherwise beautiful shot.', '2009-01-05 13:53:23.000000', NULL, 1),
(5172884, 753130, 70265, '<td valign="top">Top three. Love the tilt, subject matter, colors, border, everything.</td>', 'Top three. Love the tilt, subject matter, colors, border, everything.', '2009-01-05 13:53:25.000000', NULL, 1),
(5172885, 753177, 96751, '<td valign="top">Marvelous.  A tighter crop without the wave - making the foam cross the center - would make it even better for me.</td>', 'Marvelous.  A tighter crop without the wave - making the foam cross the center - would make it even better for me.', '2009-01-05 13:54:30.000000', NULL, 1),
(5172886, 752696, 96751, '<td valign="top">Great use of sand :-)</td>', 'Great use of sand :-)', '2009-01-05 13:54:43.000000', NULL, 1),
(5172887, 751377, 96751, '<td valign="top">Subtle and lovely.  Since you have to scroll down to "get" the entire picture, some folks might miss it.</td>', 'Subtle and lovely.  Since you have to scroll down to "get" the entire picture, some folks might miss it.', '2009-01-05 13:55:24.000000', NULL, 1),
(5172888, 753084, 44825, '<td valign="top">Love it it is worth a 10</td>', 'Love it it is worth a 10', '2009-01-05 13:57:55.000000', NULL, 1),
(5172889, 753189, 96751, '<td valign="top">Gorgeous picture.  Incredible colors and balance.  Won''t give it a 10 because it doesn''t say "sand" to me.</td>', 'Gorgeous picture.  Incredible colors and balance.  Won''t give it a 10 because it doesn''t say "sand" to me.', '2009-01-05 13:58:08.000000', NULL, 1),
(5172890, 753185, 96751, '<td valign="top">Wow.  This is incredible.  I almost wish it was in b/w.</td>', 'Wow.  This is incredible.  I almost wish it was in b/w.', '2009-01-05 13:58:47.000000', NULL, 1),
(5172891, 752861, 96751, '<td valign="top">We have sands of every color in this challenge!  Wish the sand was as sharp as the clouds...</td>', 'We have sands of every color in this challenge!  Wish the sand was as sharp as the clouds...', '2009-01-05 13:59:36.000000', NULL, 1),
(5172892, 753191, 96751, '<td valign="top">Very nice.  Colors and motion.  Maybe the dof is too shallow, and the band of focus too small, but a lively capture.</td>', 'Very nice.  Colors and motion.  Maybe the dof is too shallow, and the band of focus too small, but a lively capture.', '2009-01-05 14:00:59.000000', NULL, 1),
(5172894, 753222, 96751, '<td valign="top">So how much did he get paid?....  Interesting idea.  A bit freaky.</td>', 'So how much did he get paid?....  Interesting idea.  A bit freaky.', '2009-01-05 14:01:50.000000', NULL, 1),
(5172920, 752231, 2764, '<td valign="top">lovely lovely lovely</td>', 'lovely lovely lovely', '2009-01-05 14:20:58.000000', NULL, 1),
(5172946, 752738, 78455, '<td valign="top">Alittle bit of paradise! love it!</td>', 'Alittle bit of paradise! love it!', '2009-01-05 14:49:28.000000', NULL, 1),
(5172957, 753174, 78455, '<td valign="top">Ribbon Contender...and IMO, way ahead of anything else I''ve seen so far! Larus???<br/> <br/>Love the choice of volcanic sand (different) and white for the dress to contrast well against the dark and cool tones. 8<br/> <br/>My winner!!!</td>', 'Ribbon Contender...and IMO, way ahead of anything else I''ve seen so far! Larus??? Love the choice of volcanic sand (different) and white for the dress to contrast well against the dark and cool tones. 8 My winner!!!', '2009-01-05 15:00:08.000000', NULL, 1),
(5173022, 752974, 99175, '<td valign="top">Personally think a bit too much contrast and saturation, but otherwise a very nice photo.</td>', 'Personally think a bit too much contrast and saturation, but otherwise a very nice photo.', '2009-01-05 15:44:39.000000', NULL, 1),
(5173024, 753130, 99175, '<td valign="top">Personally think the border distracts from the picture a bit, mostly due to the different sizes top and bottom vs the sides.<br/> <br/>Otherwise great picture.</td>', 'Personally think the border distracts from the picture a bit, mostly due to the different sizes top and bottom vs the sides. Otherwise great picture.', '2009-01-05 15:45:49.000000', NULL, 1),
(5173025, 751908, 99175, '<td valign="top">interesting concept, would have liked the sea shell to have sharper focus I think though.  Little more DOF, otherwise great!</td>', 'interesting concept, would have liked the sea shell to have sharper focus I think though.  Little more DOF, otherwise great!', '2009-01-05 15:48:27.000000', NULL, 1),
(5173029, 753154, 99175, '<td valign="top">nice picture, would be better IMO if the watch hands were sharper focus.</td>', 'nice picture, would be better IMO if the watch hands were sharper focus.', '2009-01-05 15:49:41.000000', NULL, 1),
(5173032, 752795, 99175, '<td valign="top">I think the shell should be sharper focus...</td>', 'I think the shell should be sharper focus...', '2009-01-05 15:50:46.000000', NULL, 1),
