INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5176137, 753029, 91496, '<td valign="top">Like the idea and the composition.  The lighting is a bit harsh with the dark shadows whitish sparkes.</td>', 'Like the idea and the composition.  The lighting is a bit harsh with the dark shadows whitish sparkes.', '2009-01-06 23:06:51.000000', NULL, 1),
(5176139, 753095, 73056, '<td valign="top">A really nice abstract!</td>', 'A really nice abstract!', '2009-01-06 23:07:08.000000', NULL, 1),
(5176146, 752576, 73056, '<td valign="top">Nice take on the hourglass!</td>', 'Nice take on the hourglass!', '2009-01-06 23:08:34.000000', NULL, 1),
(5176153, 753021, 91496, '<td valign="top">I like the contrasting colors and textures of the sand.  This is a really neat idea.  The crop is tight on the top cutting off the tip of the "mountain".  The graphic is a little on the silly side, although the driver and camels line up realistcally.</td>', 'I like the contrasting colors and textures of the sand.  This is a really neat idea.  The crop is tight on the top cutting off the tip of the "mountain".  The graphic is a little on the silly side, although the driver and camels line up realistcally.', '2009-01-06 23:10:16.000000', NULL, 1),
(5176167, 752970, 73056, '<td valign="top">Yahoo!</td>', 'Yahoo!', '2009-01-06 23:12:18.000000', NULL, 1),
(5176172, 752676, 73056, '<td valign="top">Other worldly. Nice shot.</td>', 'Other worldly. Nice shot.', '2009-01-06 23:12:58.000000', NULL, 1),
(5176175, 752195, 91496, '<td valign="top">Nice take on the challenge.  I like the lighting as it reflects off the nails,less so on the tops of the fingers.  The backdrop blue/green corner seems out of place.  Crop seems tight to the top.</td>', 'Nice take on the challenge.  I like the lighting as it reflects off the nails,less so on the tops of the fingers.  The backdrop blue/green corner seems out of place.  Crop seems tight to the top.', '2009-01-06 23:13:24.000000', NULL, 1),
(5176185, 753095, 91496, '<td valign="top">Nice abstract view of whatever it is.  Great textures and lighting.  Not sure it really says "sand" a lot to me.</td>', 'Nice abstract view of whatever it is.  Great textures and lighting.  Not sure it really says "sand" a lot to me.', '2009-01-06 23:14:47.000000', NULL, 1),
(5176186, 751377, 73056, '<td valign="top">Trying to combine 2 hobbies into 1?</td>', 'Trying to combine 2 hobbies into 1?', '2009-01-06 23:14:49.000000', NULL, 1),
(5176187, 753007, 73056, '<td valign="top">Nice shot and comp.</td>', 'Nice shot and comp.', '2009-01-06 23:15:06.000000', NULL, 1),
(5176189, 752931, 73056, '<td valign="top">Nicely shot.</td>', 'Nicely shot.', '2009-01-06 23:15:31.000000', NULL, 1),
(5176194, 752332, 73056, '<td valign="top">Did you put that there? Nice find!</td>', 'Did you put that there? Nice find!', '2009-01-06 23:16:19.000000', NULL, 1),
(5176196, 752269, 73056, '<td valign="top">Cute - polished toes and all.</td>', 'Cute - polished toes and all.', '2009-01-06 23:16:45.000000', NULL, 1),
(5176200, 752974, 73056, '<td valign="top">Nicely shot!</td>', 'Nicely shot!', '2009-01-06 23:17:25.000000', NULL, 1),
(5176201, 753177, 91496, '<td valign="top">Nice shot.  Good composition Love how caught the foaming crest of the little wave.  Sneaker marks are a minor distraction.<br/> <br/>"2008 washed away by the crashing waves of time"</td>', 'Nice shot.  Good composition Love how caught the foaming crest of the little wave.  Sneaker marks are a minor distraction. "2008 washed away by the crashing waves of time"', '2009-01-06 23:17:30.000000', NULL, 1),
(5176212, 753188, 91496, '<td valign="top">Nice capture with a good use of the narrow DOF to emphasis the bird and his presence on the narrow strip of in-focus sand.  I might have cloned out the half a bokeh on the top right but that is a small nit.</td>', 'Nice capture with a good use of the narrow DOF to emphasis the bird and his presence on the narrow strip of in-focus sand.  I might have cloned out the half a bokeh on the top right but that is a small nit.', '2009-01-06 23:20:30.000000', NULL, 1),
(5176221, 753215, 73056, '<td valign="top">:) Me likes this cutie! :) Well shot!</td>', ':) Me likes this cutie! :) Well shot!', '2009-01-06 23:21:54.000000', NULL, 1),
(5176230, 753154, 91496, '<td valign="top">Nice contrast of the brown gritty sand and the smoothe silver watch.  Creamy bokeh on top is nice.  Narrow DOF may be too narrow as very little of the watch is actually in focus.</td>', 'Nice contrast of the brown gritty sand and the smoothe silver watch.  Creamy bokeh on top is nice.  Narrow DOF may be too narrow as very little of the watch is actually in focus.', '2009-01-06 23:24:07.000000', NULL, 1),
(5176238, 752716, 73056, '<td valign="top">Nice shot and processing. It has a surreal/isolated feeling to it.</td>', 'Nice shot and processing. It has a surreal/isolated feeling to it.', '2009-01-06 23:25:22.000000', NULL, 1),
(5176253, 753099, 73056, '<td valign="top">Absolutely love it! 10! In my top 3.</td>', 'Absolutely love it! 10! In my top 3.', '2009-01-06 23:27:28.000000', NULL, 1),
(5176254, 753130, 73056, '<td valign="top">Gorgeous! Love the angle, comp and processing. 10.</td>', 'Gorgeous! Love the angle, comp and processing. 10.', '2009-01-06 23:27:50.000000', NULL, 1),
(5176258, 751501, 73056, '<td valign="top">Great shot, lighting and processing! Good luck!</td>', 'Great shot, lighting and processing! Good luck!', '2009-01-06 23:28:35.000000', NULL, 1),
(5176259, 752693, 91496, '<td valign="top">Nice curves around the lake bed and in the "U" in the tree line.  Very flat color-wise with all dull tones, except the tiny red and green objects.  Much of the photo is filled with a featureless sky, which makes the compostition kind of static.</td>', 'Nice curves around the lake bed and in the "U" in the tree line.  Very flat color-wise with all dull tones, except the tiny red and green objects.  Much of the photo is filled with a featureless sky, which makes the compostition kind of static.', '2009-01-06 23:28:42.000000', NULL, 1),
(5176279, 753215, 91496, '<td valign="top">That is surely in your face.  I like all the sand on his nose and whiskers.  The exteme close-up and centered compostion are perhaps a bit much.  Usually the eyes are key to a portrait and his a black and featureless.</td>', 'That is surely in your face.  I like all the sand on his nose and whiskers.  The exteme close-up and centered compostion are perhaps a bit much.  Usually the eyes are key to a portrait and his a black and featureless.', '2009-01-06 23:32:32.000000', NULL, 1),
(5176287, 753227, 91496, '<td valign="top">Nice composition wiht the sand flowing down like that.  The noisy/grainy approach kind of works for me here.  The tones are a little bland with all the grays.  Maybe different lighting would have given you blacker blacks and whiter whites.</td>', 'Nice composition wiht the sand flowing down like that.  The noisy/grainy approach kind of works for me here.  The tones are a little bland with all the grays.  Maybe different lighting would have given you blacker blacks and whiter whites.', '2009-01-06 23:35:31.000000', NULL, 1),
(5176297, 752768, 91496, '<td valign="top">Cool sky with all the muted colors.  Composition works well with the dogs.  Tilted horizon detracts a bit.  The googles add a point of color but not sure they really add much else.</td>', 'Cool sky with all the muted colors.  Composition works well with the dogs.  Tilted horizon detracts a bit.  The googles add a point of color but not sure they really add much else.', '2009-01-06 23:38:37.000000', NULL, 1),
(5176312, 752832, 91496, '<td valign="top">I like how all the differnt elements balance each other.  Nice contrast between the blues and greens.  Focus seems a bit off or perhaps it is oversharpend.</td>', 'I like how all the differnt elements balance each other.  Nice contrast between the blues and greens.  Focus seems a bit off or perhaps it is oversharpend.', '2009-01-06 23:48:43.000000', NULL, 1),
(5176717, 753196, 102024, '<td valign="top">Very beautiful.  I kinda wish the dark line in the top left corner was cropped off or dealt with in some way.  It is somewhat distracting.</td>', 'Very beautiful.  I kinda wish the dark line in the top left corner was cropped off or dealt with in some way.  It is somewhat distracting.', '2009-01-07 01:56:02.000000', NULL, 1),
(5176792, 753086, 66709, '<td valign="top">This look familiar about a year ago  nice image</td>', 'This look familiar about a year ago  nice image', '2009-01-07 03:22:14.000000', NULL, 1),
(5177059, 753064, 68413, '<td valign="top">This is the first image I saw when I opened this challenge for voting...love it . Brilliant colours and textures in the rock.....10</td>', 'This is the first image I saw when I opened this challenge for voting...love it . Brilliant colours and textures in the rock.....10', '2009-01-07 05:35:27.000000', NULL, 1),
(5177063, 752871, 68413, '<td valign="top">Excellent POV &amp; DOF - 9</td>', 'Excellent POV & DOF - 9', '2009-01-07 05:36:56.000000', NULL, 1),
(5177065, 753130, 68413, '<td valign="top">Excellent image. Like the angular POV - 9</td>', 'Excellent image. Like the angular POV - 9', '2009-01-07 05:37:57.000000', NULL, 1),
(5177067, 752861, 68413, '<td valign="top">Lovely colours in the sky, dunes and rocks. Nice POV - 9</td>', 'Lovely colours in the sky, dunes and rocks. Nice POV - 9', '2009-01-07 05:39:09.000000', NULL, 1),
(5177068, 752201, 68413, '<td valign="top">Like this image a lot. Has an eerie feel to it. - 8</td>', 'Like this image a lot. Has an eerie feel to it. - 8', '2009-01-07 05:40:16.000000', NULL, 1),
(5177070, 752448, 68413, '<td valign="top">Lovely slow shutter. Great shot. - 8</td>', 'Lovely slow shutter. Great shot. - 8', '2009-01-07 05:41:29.000000', NULL, 1),
(5177073, 752332, 68413, '<td valign="top">Cool shot. Even if contrived. - 8</td>', 'Cool shot. Even if contrived. - 8', '2009-01-07 05:42:33.000000', NULL, 1),
(5177159, 753215, 75192, '<td valign="top">Very, very cute!</td>', 'Very, very cute!', '2009-01-07 06:36:00.000000', NULL, 1),
(5177160, 753095, 75192, '<td valign="top">Very good abstract. I would have cropped more off the bottom though. An  original and innovative approach to the challenge.</td>', 'Very good abstract. I would have cropped more off the bottom though. An  original and innovative approach to the challenge.', '2009-01-07 06:36:07.000000', NULL, 1),
(5177272, 752231, 84656, '<td valign="top">I quite like this image of the bride and groom, something different.  Not sure how it will do in the challenge though. Also not sure what on the beach created the white streaks, (some grass?) but I think they overpower the overall effect of what you were hoping to create.</td>', 'I quite like this image of the bride and groom, something different.  Not sure how it will do in the challenge though. Also not sure what on the beach created the white streaks, (some grass?) but I think they overpower the overall effect of what you were hoping to create.', '2009-01-07 08:02:51.000000', NULL, 1),
(5177277, 752738, 84656, '<td valign="top">Made me smile.  Well taken too :)</td>', 'Made me smile.  Well taken too :)', '2009-01-07 08:06:52.000000', NULL, 1),
(5177286, 752201, 84656, '<td valign="top">I''m sure you have received a few comments about the horizon, otherwise a great image with plenty of atmosphere.</td>', 'I''m sure you have received a few comments about the horizon, otherwise a great image with plenty of atmosphere.', '2009-01-07 08:13:51.000000', NULL, 1),
(5177298, 751306, 84656, '<td valign="top">Always check your horizon.  Lovely colours and textures.</td>', 'Always check your horizon.  Lovely colours and textures.', '2009-01-07 08:20:58.000000', NULL, 1),
(5177375, 752511, 84656, '<td valign="top">Image could do with a colour boost and check the horizon.</td>', 'Image could do with a colour boost and check the horizon.', '2009-01-07 08:58:47.000000', NULL, 1),
(5177378, 753130, 84656, '<td valign="top">The angle here works well.  Great colours and awesome sky.  Good luck.</td>', 'The angle here works well.  Great colours and awesome sky.  Good luck.', '2009-01-07 08:59:45.000000', NULL, 1),
(5177466, 753196, 84656, '<td valign="top">Reckon it''s better with about 17% cropped off the top. otherwise love it.</td>', 'Reckon it''s better with about 17% cropped off the top. otherwise love it.', '2009-01-07 09:26:34.000000', NULL, 1),
(5177479, 753205, 84656, '<td valign="top">Love the simplicity of this image.</td>', 'Love the simplicity of this image.', '2009-01-07 09:28:59.000000', NULL, 1),
(5178694, 752677, 8759, '<td valign="top">I like the out of the box approach and the stop motion. With no influence to the score I strongly dislike the frame. Good luck</td>', 'I like the out of the box approach and the stop motion. With no influence to the score I strongly dislike the frame. Good luck', '2009-01-07 19:05:19.000000', NULL, 1),
(5178722, 752559, 68947, '<td valign="top">LOL...this is so cute!  Especially true for those of us living in areas with snow and unable to even find SAND!  In my opinion, I was thinking that perhaps, having angled the duck and snowman more towards the front of the sand so that the background was also sand, or perhaps, a sky blue background (poster board or construction paper?) would have driven that idea home a bit more.  However, I love this idea as it made me smile!! 9</td>', 'LOL...this is so cute!  Especially true for those of us living in areas with snow and unable to even find SAND!  In my opinion, I was thinking that perhaps, having angled the duck and snowman more towards the front of the sand so that the background was also sand, or perhaps, a sky blue background (poster board or construction paper?) would have driven that idea home a bit more.  However, I love this idea as it made me smile!! 9', '2009-01-07 19:36:36.000000', NULL, 1),
(5178723, 752767, 86322, '<td valign="top">Awesome and powerful image. One of my favorite</td>', 'Awesome and powerful image. One of my favorite', '2009-01-07 19:36:51.000000', NULL, 1),
(5178726, 753191, 86322, '<td valign="top">Love the anlge this photo was taken from, the composition is great also.</td>', 'Love the anlge this photo was taken from, the composition is great also.', '2009-01-07 19:37:37.000000', NULL, 1),
(5178729, 753130, 86322, '<td valign="top">The tilt works for me here. Nice colors and comp.</td>', 'The tilt works for me here. Nice colors and comp.', '2009-01-07 19:37:57.000000', NULL, 1),
(5178730, 753026, 86322, '<td valign="top">Nice close up, you can see all de details.</td>', 'Nice close up, you can see all de details.', '2009-01-07 19:38:14.000000', NULL, 1),
(5178731, 752693, 68947, '<td valign="top">Love the angle and perspective in this one.</td>', 'Love the angle and perspective in this one.', '2009-01-07 19:38:26.000000', NULL, 1),
(5178733, 753099, 86322, '<td valign="top">Very powerful image. I like the B/W and the story behind the photo.</td>', 'Very powerful image. I like the B/W and the story behind the photo.', '2009-01-07 19:38:48.000000', NULL, 1),
(5178736, 752800, 86322, '<td valign="top">Like the contrast of colors, and the angle it was taken</td>', 'Like the contrast of colors, and the angle it was taken', '2009-01-07 19:39:45.000000', NULL, 1),
(5178737, 752799, 68947, '<td valign="top">very pretty scenery but, I think it''s a little oversaturated in reds???</td>', 'very pretty scenery but, I think it''s a little oversaturated in reds???', '2009-01-07 19:39:50.000000', NULL, 1),
(5178738, 752752, 86322, '<td valign="top">Very clear and vivid photo, it was so early in the morning and yet you still manage to catch so much light in the foreground.</td>', 'Very clear and vivid photo, it was so early in the morning and yet you still manage to catch so much light in the foreground.', '2009-01-07 19:40:56.000000', NULL, 1),
(5178741, 753130, 68947, '<td valign="top">Interesting editing as the sand looks more like a patina''d piece of copper than sand.  I''ll have to find out what you did during the editing.  Love the angle of this and the border works well.  Should do well.</td>', 'Interesting editing as the sand looks more like a patina''d piece of copper than sand.  I''ll have to find out what you did during the editing.  Love the angle of this and the border works well.  Should do well.', '2009-01-07 19:41:37.000000', NULL, 1),
(5178742, 752871, 86322, '<td valign="top">Nice subject, would''ve loved to see it in one corner rather than the center.</td>', 'Nice subject, would''ve loved to see it in one corner rather than the center.', '2009-01-07 19:41:47.000000', NULL, 1),
(5178743, 752744, 86322, '<td valign="top">Very misterious and simple but to the point.</td>', 'Very misterious and simple but to the point.', '2009-01-07 19:42:14.000000', NULL, 1),
(5178745, 752686, 86322, '<td valign="top">Nice close up and use of DOF.</td>', 'Nice close up and use of DOF.', '2009-01-07 19:42:36.000000', NULL, 1),
(5178746, 752793, 68947, '<td valign="top">It takes a moment of looking to really appreciate this shot.  I love the lighting on this and the bubbles that you''ve captured.  8</td>', 'It takes a moment of looking to really appreciate this shot.  I love the lighting on this and the bubbles that you''ve captured.  8', '2009-01-07 19:42:44.000000', NULL, 1),
(5178748, 752676, 86322, '<td valign="top">Very nice sunrise. Love the rocks and general composition.</td>', 'Very nice sunrise. Love the rocks and general composition.', '2009-01-07 19:43:14.000000', NULL, 1),
(5178750, 752575, 68947, '<td valign="top">Oh, now this is precious!!!  I love the idea of this and the fact that you found a way to incorporate sand in your shot and the way that  you''re portrayed it.  I''m sure that it''s not going to hit a lot of voter''s tastes as it''s not going to match up to the lovely sand scenes that the warmer climates can capture, but I like it!!!  9</td>', 'Oh, now this is precious!!!  I love the idea of this and the fact that you found a way to incorporate sand in your shot and the way that  you''re portrayed it.  I''m sure that it''s not going to hit a lot of voter''s tastes as it''s not going to match up to the lovely sand scenes that the warmer climates can capture, but I like it!!!  9', '2009-01-07 19:44:05.000000', NULL, 1),
(5178754, 752795, 68947, '<td valign="top">Very pretty!  I lov ethe softer focus too! Really works!  9</td>', 'Very pretty!  I lov ethe softer focus too! Really works!  9', '2009-01-07 19:44:50.000000', NULL, 1),
(5178755, 752652, 86322, '<td valign="top">Great use of the light here, love the black sand</td>', 'Great use of the light here, love the black sand', '2009-01-07 19:45:49.000000', NULL, 1),
(5178757, 753196, 68947, '<td valign="top">Very abstract!  Love the lighting on this and the fact that it isn''t the usual type of scenery!  Nicely done! 10</td>', 'Very abstract!  Love the lighting on this and the fact that it isn''t the usual type of scenery!  Nicely done! 10', '2009-01-07 19:46:09.000000', NULL, 1),
(5178762, 753026, 68947, '<td valign="top">I really like this as it''s quite abstract yet, very artsy at the same time.  LOVE the lighting on this and the B&amp;W works very well!  10</td>', 'I really like this as it''s quite abstract yet, very artsy at the same time.  LOVE the lighting on this and the B&W works very well!  10', '2009-01-07 19:47:09.000000', NULL, 1),
(5178764, 753075, 86322, '<td valign="top">Like the tone, you can just fly to this place by looking at it.</td>', 'Like the tone, you can just fly to this place by looking at it.', '2009-01-07 19:47:57.000000', NULL, 1),
(5178765, 752195, 68947, '<td valign="top">Love the textures to this and the lighting!</td>', 'Love the textures to this and the lighting!', '2009-01-07 19:48:12.000000', NULL, 1),
