INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5184675, 752251, 76335, '<td valign="top">Great colors, clarity.</td>', 'Great colors, clarity.', '2009-01-11 10:04:08.000000', NULL, 1),
