(5184716, 751669, 76335, '<td valign="top">I think a lot of folks missed opportunities to show people playing in the sand. I guess it''s the wrong time of season, but in any case, this was a welcome shot. Great energy and a lot of fun. Technically it''s not perfect, but the idea of playfulness and bonding is conveyed perfectly. Upping this to a seven.</td>', 'I think a lot of folks missed opportunities to show people playing in the sand. I guess it''s the wrong time of season, but in any case, this was a welcome shot. Great energy and a lot of fun. Technically it''s not perfect, but the idea of playfulness and bonding is conveyed perfectly. Upping this to a seven.', '2009-01-11 10:22:01.000000', NULL, 1),
(5184717, 753077, 76335, '<td valign="top">Nicely composed.</td>', 'Nicely composed.', '2009-01-11 10:22:11.000000', NULL, 1),
(5184718, 752596, 76335, '<td valign="top">Beautiful, stunning even. Great shadows and lighting here.</td>', 'Beautiful, stunning even. Great shadows and lighting here.', '2009-01-11 10:22:58.000000', NULL, 1),
(5184719, 752985, 76335, '<td valign="top">Nicely composed and well seen.</td>', 'Nicely composed and well seen.', '2009-01-11 10:23:15.000000', NULL, 1),
(5184721, 752332, 76335, '<td valign="top">A little dark, but it works well all the same.</td>', 'A little dark, but it works well all the same.', '2009-01-11 10:23:49.000000', NULL, 1),
(5184725, 752462, 76335, '<td valign="top">Border is a little constraining; I would rather have had the extra detail, because this is really original and moving.</td>', 'Border is a little constraining; I would rather have had the extra detail, because this is really original and moving.', '2009-01-11 10:24:59.000000', NULL, 1),
(5184727, 753199, 76335, '<td valign="top">White balance strikes me as a bit on the cool side...</td>', 'White balance strikes me as a bit on the cool side...', '2009-01-11 10:25:47.000000', NULL, 1),
