(5184730, 752931, 76335, '<td valign="top">Needs a bit more sharpness...</td>', 'Needs a bit more sharpness...', '2009-01-11 10:27:02.000000', NULL, 1),
(5184731, 753154, 76335, '<td valign="top">A bit soft...</td>', 'A bit soft...', '2009-01-11 10:27:11.000000', NULL, 1),
