(5184783, 752511, 79720, '<td valign="top">At 77kb, you''ve only used a third of the allowed 200KB for image size. Especially with a Seascape, that gives some JPEG artifacts at the horizon. That horizon is nice &amp; straight, though!</td>', 'At 77kb, you''ve only used a third of the allowed 200KB for image size. Especially with a Seascape, that gives some JPEG artifacts at the horizon. That horizon is nice & straight, though!', '2009-01-11 11:28:15.000000', NULL, 1),
(5184786, 753222, 79720, '<td valign="top">I''ll give you props for going the distance on the setup. Not very aesthetically pleasing, though...kinds gross, actually. <b>:</b>-)</td>', 'I''ll give you props for going the distance on the setup. Not very aesthetically pleasing, though...kinds gross, actually. :-)', '2009-01-11 11:29:19.000000', NULL, 1),
(5184790, 753174, 79720, '<td valign="top">Um, front page, unless the trolls think the sand should be the subject. Beautiful model, great composition and adequate lighting. A 9 from me.</td>', 'Um, front page, unless the trolls think the sand should be the subject. Beautiful model, great composition and adequate lighting. A 9 from me.', '2009-01-11 11:30:49.000000', NULL, 1),
(5184792, 752738, 79720, '<td valign="top">Love the lighting!</td>', 'Love the lighting!', '2009-01-11 11:31:21.000000', NULL, 1),
(5184793, 753130, 79720, '<td valign="top">Interesting perspective, great tones, awesome sky.</td>', 'Interesting perspective, great tones, awesome sky.', '2009-01-11 11:32:15.000000', NULL, 1),
