(5184814, 753064, 79720, '<td valign="top">Freakin'' amazing light capture. I think I''ve seen this location before.</td>', 'Freakin'' amazing light capture. I think I''ve seen this location before.', '2009-01-11 11:38:54.000000', NULL, 1),
