(5186103, 752201, 43088, '<td valign="top">Intersting (to me) personal note- my three highest scoring photos so far were all taken with a different camera. Highest was with a point and shoot (Fuji F31fd converted to shoot in infrared), a DSLR (Nikon D80), and a "prosumer" (Konica Minolta A200 which I no longer have but a friend is enjoying).</td>', 'Intersting (to me) personal note- my three highest scoring photos so far were all taken with a different camera. Highest was with a point and shoot (Fuji F31fd converted to shoot in infrared), a DSLR (Nikon D80), and a "prosumer" (Konica Minolta A200 which I no longer have but a friend is enjoying).', '2009-01-12 01:21:49.000000', NULL, 0),
(5186113, 752864, 30861, '<td valign="top">Oh, you did GREAT! Bravo! I couldn''t be more impressed...</td>', 'Oh, you did GREAT! Bravo! I couldn''t be more impressed...', '2009-01-12 01:32:31.000000', NULL, 0),
(5186116, 753188, 30861, '<td valign="top">Hey, nobody shoots seagulls... jejeje I actually like this one in its attentive serenity.</td>', 'Hey, nobody shoots seagulls... jejeje I actually like this one in its attentive serenity.', '2009-01-12 01:35:00.000000', NULL, 0),
(5186120, 753064, 66635, '<td valign="top">Wonderful!  Congrats.</td>', 'Wonderful!  Congrats.', '2009-01-12 01:37:06.000000', NULL, 0),
(5186127, 752767, 30214, '<td valign="top">wonderful minimalism. And a perfect rim light on your ant, did you shoot him in a studio?</td>', 'wonderful minimalism. And a perfect rim light on your ant, did you shoot him in a studio?', '2009-01-12 01:42:31.000000', NULL, 0),
(5186140, 753199, 66635, '<td valign="top">Well, I''m disappointed in how this did.  My thoughts are that I made it too blue and that I should have used a greater depth of field so that the sand, too, was in focus.  Anyone else have any other ideas?  I told my wife it would have helped if she''d been wearing a thong, but she said her thong days are over! :-(</td>', 'Well, I''m disappointed in how this did.  My thoughts are that I made it too blue and that I should have used a greater depth of field so that the sand, too, was in focus.  Anyone else have any other ideas?  I told my wife it would have helped if she''d been wearing a thong, but she said her thong days are over! :-(', '2009-01-12 01:51:08.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5186159, 752201, 76430, '<td valign="top">Congratulations on the ribbon!  Great shot.  You managed to get the fog that I was unable to get when I went to the same location (I think, or is it Crystal Pier, OB Pier or IB Pier?) when it was foggy inland but not so foggy in La Jolla.  I love the sharp surfer shapes against the hazy ocean and Scripps Pier.</td>', 'Congratulations on the ribbon!  Great shot.  You managed to get the fog that I was unable to get when I went to the same location (I think, or is it Crystal Pier, OB Pier or IB Pier?) when it was foggy inland but not so foggy in La Jolla.  I love the sharp surfer shapes against the hazy ocean and Scripps Pier.', '2009-01-12 02:17:06.000000', NULL, 0),
(5186163, 752630, 72134, '<td valign="top">I''ve notised that some thinks I made this in the sand, but the fact is that I didn''nt touch it, the wind made this clock all by himself</td>', 'I''ve notised that some thinks I made this in the sand, but the fact is that I didn''nt touch it, the wind made this clock all by himself', '2009-01-12 02:22:10.000000', NULL, 0),
(5186166, 753064, 68586, '<td valign="top">Hey Lev - congrats on the Blue - tremendous shot.</td>', 'Hey Lev - congrats on the Blue - tremendous shot.', '2009-01-12 02:28:03.000000', NULL, 0),
(5186170, 752864, 33352, '<td valign="top">And I would have been more impressed had you cropped out the power lines, excellent work.</td>', 'And I would have been more impressed had you cropped out the power lines, excellent work.', '2009-01-12 02:38:50.000000', NULL, 0),
(5186175, 752677, 79357, '<td valign="top">I voted 5 during the competition but now when I look again, this really grows on me! With a little better light conditions, this would be a really nice one!!</td>', 'I voted 5 during the competition but now when I look again, this really grows on me! With a little better light conditions, this would be a really nice one!!', '2009-01-12 02:46:01.000000', NULL, 0),
